CREATE TABLE knowledge_graph_nodes (id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL, kind varchar(32) NOT NULL, label varchar(300) NOT NULL, description text NOT NULL DEFAULT '', course_id varchar(64), source_revision_id varchar(64), source_locator varchar(255), provenance_sha256 varchar(64), state varchar(24) NOT NULL, origin varchar(24) NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE INDEX ix_kg_nodes_tenant ON knowledge_graph_nodes(tenant_id); CREATE INDEX ix_kg_nodes_kind ON knowledge_graph_nodes(kind); CREATE INDEX ix_kg_nodes_course ON knowledge_graph_nodes(course_id); CREATE INDEX ix_kg_nodes_state ON knowledge_graph_nodes(state);
CREATE TABLE knowledge_graph_relations (id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL, source_id varchar(64) NOT NULL, target_id varchar(64) NOT NULL, kind varchar(32) NOT NULL, rationale text NOT NULL, confidence integer NOT NULL CHECK(confidence BETWEEN 0 AND 100), state varchar(24) NOT NULL, origin varchar(24) NOT NULL, source_revision_id varchar(64), provenance_sha256 varchar(64), version integer NOT NULL DEFAULT 1, created_by varchar(64) NOT NULL, validated_by varchar(64), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, CHECK(source_id <> target_id));
CREATE INDEX ix_kg_rel_tenant ON knowledge_graph_relations(tenant_id); CREATE INDEX ix_kg_rel_source ON knowledge_graph_relations(source_id); CREATE INDEX ix_kg_rel_target ON knowledge_graph_relations(target_id); CREATE INDEX ix_kg_rel_kind ON knowledge_graph_relations(kind); CREATE INDEX ix_kg_rel_state ON knowledge_graph_relations(state);
CREATE UNIQUE INDEX uq_kg_live_relation ON knowledge_graph_relations(tenant_id,source_id,target_id,kind) WHERE state IN ('candidate','validated','published');
